{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Tetrabenazine, which shares the benzoquinolizine core with the query, has very low oral bioavailability (mean 0.049, range 0.001-0.085), supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Valbenazine, a tetrabenazine analog with a side chain, has ~49% absolute oral bioavailability, supporting high F, but the side chain is a prodrug ester, not a basic amine.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C62"],
      "claim": "Almorexant, a tetrahydroisoquinoline with a dimethoxyphenyl, has ~11% absolute oral bioavailability, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Verapamil, which has a basic amine and veratrole groups, has low oral bioavailability (mostly 18-24%), supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Noscapine, an isoquinoline with a dimethoxyphenyl, has ~30% absolute oral bioavailability, supporting high F, but with a wide range.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low oral bioavailability (F below 20%) based on the strong structural similarity to tetrabenazine, which has very low F, and the metabolic liability of the basic amine side chain, despite some positive signals from valbenazine and noscapine.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "Uncertainty about the effect of the basic amine side chain on absorption and first-pass metabolism.",
    "Valbenazine's high F is from a prodrug ester, not a basic amine."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

